// 3D model of the right temporal bone and ear from Z-Anatomy meshes (CC BY-SA
// 4.0, based on BodyParts3D): the temporal bone (translucent), auricle,
// eardrum, ossicles, cochlea and labyrinth, the facial nerve through the bone,
// chorda tympani, VIII, the petrous carotid and the sigmoid sinus. The ear
// canal, mastoid antrum and air cells, tensor tympani and stapedius are
// sculpted for this app. Geometry and the traced courses live in
// data/temporal-bone-meshes.js, generated by tools/export_zanatomy.py.
// Coordinates are centimetres centred on the middle ear: +y = superior,
// +z = anterior, and lateral (the patient's right) is -x.

window.ANATOMY = window.ANATOMY || { regions: {} };
window.ANATOMY.models = window.ANATOMY.models || {};

window.ANATOMY.models.temporal_bone = {
  // Default view: from the right side and a little behind, looking through
  // the translucent mastoid at the middle ear and labyrinth.
  camera: { target: [0.2, 0.1, -0.2], radius: 11, theta: -1.95, phi: 1.42 },

  views: {
    lateral: [-Math.PI / 2, Math.PI / 2],
    inferior: [-1.2, 0.25],
    anterior: [0, Math.PI / 2]
  },
  viewLabels: { inferior: "From above", anterior: "Front" },

  // Starting axial level (0 = bottom, 1 = top): through the middle ear.
  sectionLevel: 0.5,

  look: {
    temporal: { kind: "bone", opacity: 0.28 },
    auricle: { kind: "cartilage", color: 0xe8b9a6, opacity: 0.55 },
    eac: { kind: "mucosa", color: 0xe7b3a3, opacity: 0.45 },
    tympanic_membrane: { kind: "cartilage", color: 0xd9c9c0, opacity: 0.7 },
    malleus: { kind: "bone", color: 0xf1e3c2 },
    incus: { kind: "bone", color: 0xead8b0 },
    stapes: { kind: "bone", color: 0xe3cc98 },
    tensor_tympani: { kind: "muscle", color: 0xb5524a },
    stapedius: { kind: "muscle", color: 0xa94b45 },
    antrum: { kind: "space", color: 0x9fc7ea, opacity: 0.55 },
    air_cells: { kind: "space", color: 0xb7d6f0, opacity: 0.45 },
    auditory_tube: { kind: "cartilage", color: 0xd9c2b8 },
    cochlea: { kind: "gland", color: 0xe0b98c },
    labyrinth: { kind: "gland", color: 0xd7a971 },
    facial_nerve: { kind: "nerve" },
    chorda: { kind: "nerve", color: 0xf3d97a },
    cn8: { kind: "nerve", color: 0xe8c45a },
    ica: { kind: "artery" },
    sigmoid: { kind: "vein" },
    ijv: { kind: "vein" },
    digastric_post: { kind: "muscle", color: 0xa4423f, opacity: 0.8 },
    scm: { kind: "muscle", color: 0x9c3a3c, opacity: 0.6 }
  },

  build(THREE, h) {
    return h.fromMeshes("temporal_bone", this.look);
  }
};
